/* ==========================================================================
   HALOUI PHYSICAL LIQUID GLASS FLOATING SURFACE ENGINE
   (Stationary 10-layer physical optical engine for popups, overlays, modals & menus)
   ========================================================================== */
.halo-liquid-glass-surface {
  position: relative;
  isolation: isolate;
  background: rgba(255, 255, 255, 0.88);
  backdrop-filter: blur(24px) saturate(190%);
  -webkit-backdrop-filter: blur(24px) saturate(190%);
  border: 1px double rgba(51, 51, 51, 0.12);
  box-shadow:
    inset 2px -2px 1px -1px rgba(255, 255, 255, 0.95),
    inset -2px 2px 1px -1px rgba(255, 255, 255, 0.95),
    inset 6px -6px 1px -6px rgba(255, 255, 255, 0.65),
    inset -6px 6px 1px -6px rgba(255, 255, 255, 0.65),
    inset 0 0 2px rgba(0, 0, 0, 0.15),
    0 16px 40px -8px rgba(0, 0, 0, 0.18),
    0 4px 14px rgba(0, 0, 0, 0.08);
}

.dark .halo-liquid-glass-surface,
[data-stage-theme="dark"] .halo-liquid-glass-surface {
  background: rgba(18, 20, 24, 0.82);
  border: 1px double rgba(255, 255, 255, 0.16);
  box-shadow:
    inset 2px -2px 1px -1px rgba(255, 255, 255, 0.45),
    inset -2px 2px 1px -1px rgba(255, 255, 255, 0.45),
    inset 6px -6px 1px -6px rgba(255, 255, 255, 0.25),
    inset -6px 6px 1px -6px rgba(255, 255, 255, 0.25),
    inset 0 0 2px rgba(0, 0, 0, 0.8),
    0 24px 50px -12px rgba(0, 0, 0, 0.75),
    0 8px 24px -4px rgba(0, 0, 0, 0.5);
}

.halo-liquid-glass-surface::before {
  content: "";
  position: absolute;
  z-index: 1;
  inset: 0;
  border-radius: inherit;
  pointer-events: none;
  background: linear-gradient(
    45deg,
    rgba(255, 255, 255, 0.65) 0%,
    transparent 28%,
    transparent 72%,
    rgba(255, 255, 255, 0.65) 100%
  );
  filter: blur(1px);
  opacity: 0.9;
}

.dark .halo-liquid-glass-surface::before,
[data-stage-theme="dark"] .halo-liquid-glass-surface::before {
  background: linear-gradient(
    45deg,
    rgba(255, 255, 255, 0.35) 0%,
    transparent 28%,
    transparent 72%,
    rgba(255, 255, 255, 0.35) 100%
  );
}

.halo-liquid-glass-surface::after {
  content: "";
  position: absolute;
  z-index: 0;
  inset: 2px;
  border-radius: inherit;
  border: 1px solid rgba(0, 0, 0, 0.12);
  filter: blur(3px);
  pointer-events: none;
}

.dark .halo-liquid-glass-surface::after,
[data-stage-theme="dark"] .halo-liquid-glass-surface::after {
  border: 1px solid rgba(255, 255, 255, 0.1);
  filter: blur(3px);
}


@keyframes halo-indeterminate {
  0% {
    transform: translateX(-100%);
  }
  50% {
    transform: translateX(100%);
  }
  100% {
    transform: translateX(300%);
  }
}

.animate-indeterminate-slide {
  animation: halo-indeterminate 1.6s infinite ease-in-out;
}
